<?php
$titulo_pagina='Banco de Talentos';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/functions.php';verificarAutenticacao();if(($_SESSION['tipo_usuario']??'')!=='empresa')redirecionar('/');$q=trim($_GET['q']??'');$stmt=$mysqli->prepare("SELECT c.*,u.nome FROM curriculos c JOIN usuarios u ON u.id=c.usuario_id WHERE c.publico=1 AND (?='' OR c.titulo LIKE CONCAT('%',?,'%') OR c.habilidades LIKE CONCAT('%',?,'%') OR c.resumo LIKE CONCAT('%',?,'%')) ORDER BY c.atualizado_em DESC LIMIT 100");$stmt->bind_param('ssss',$q,$q,$q,$q);$stmt->execute();$cvs=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);require_once __DIR__.'/../includes/header.php';?>
<div class="container"><h1>Banco de Talentos</h1><form class="job-search"><input name="q" value="<?php echo sanitizar($q); ?>" placeholder="Cargo ou habilidade"><button>Pesquisar currículos</button></form><div class="posts-lista"><?php foreach($cvs as $cv): ?><article class="post-item"><h2><?php echo sanitizar($cv['titulo']); ?></h2><strong><?php echo sanitizar($cv['nome']); ?></strong><p><?php echo sanitizar(mb_strimwidth($cv['resumo'],0,250,'…')); ?></p><p><?php echo sanitizar($cv['habilidades']); ?></p><small><?php echo sanitizar($cv['cidade'].'/'.$cv['uf']); ?></small></article><?php endforeach; ?></div></div><?php require_once __DIR__.'/../includes/footer.php'; ?>
